document.addEventListener('DOMContentLoaded', () => {
  const section = document.querySelector('.section-traffic')
  if (section) {
    const itemList = section.querySelectorAll('.section-traffic__item')
    itemList.forEach((item) => {
      const soundAnimation = item.querySelector('.section-traffic__sound-icon')
      const soundBox = item.querySelector('.section-traffic__sound-box')
      const sound = new Audio(item.dataset.sound)
      sound.loop = true
      if (soundAnimation) {
        const animation = lottie.loadAnimation({
          container: soundAnimation,
          renderer: 'svg', // тип рендерера (может быть 'svg', 'canvas' или 'html')
          loop: true, // зацикливание анимации
          autoplay: false, // автоматический запуск анимации
          path: 'images/section-traffic/sound-animation.json' // путь к JSON-файлу с анимацией
        })

        soundBox.addEventListener('click', () => sound.play())

        item.addEventListener('mouseenter', () => {
          animation.play()
        })
        item.addEventListener('mouseleave', () => {
          animation.stop()
          sound.pause()
          sound.currentTime = 0
        })
      }
    })
  }
})